def rule(t, A):
    # skip if the breakout tick is already 1.2+ pips beyond the UHV level (spike / gap / wide-spread tick)
    return t["side"] * (t["fill"] - t["level"]) >= 1.2 * 1e-4

B7x_HTF_AGAINST.code:
def rule(t, A):
    # close > 6 pips on the wrong side of EMA(240)
    k = t["k"]; n = 240; a = 2.0 / (n + 1); j0 = max(0, k - 4 * n); e = float(A.c[j0])
    for i in range(j0 + 1, k + 1):
        e = a * float(A.c[i]) + (1 - a) * e                           # causal EMA(240) of closes up to k
    return t["side"] * (A.c[k] - e) < -6 * 1e-4

B7x_COUNTER_HTF_BOUNCE.code:
def rule(t, A):
    # 2+ humps of the trade colour but > 5 pips on the wrong side of EMA(240)
    k = t["k"]; n = 240; a = 2.0 / (n + 1); j0 = max(0, k - 4 * n); e = float(A.c[j0])
    for i in range(j0 + 1, k + 1):
        e = a * float(A.c[i]) + (1 - a) * e                           # causal EMA(240) of closes up to k
    return t["side"] * t["camStk"] >= 2 and t["side"] * (A.c[k] - e) < -5 * 1e-4

B7x_OLD_TREND.code:
def rule(t, A):
    # 4+ humps of the trade colour in a row
    return t["side"] * t["camStk"] >= 4

B7x_OLD_UHV.code:
def rule(t, A):
    # the UHV candle is 10+ minutes old at the breakout
    return t["kb"] - t["ku"] >= 10

B7x_LOUD_BREAKOUT.code:
def rule(t, A):
    # breakout minute ticks so far >= 0.9 x UHV ticks
    return t["brk_ticks_so_far"] >= 0.9 * t["uhv_v"]

B7x_HH_AGAINST.code:
def rule(t, A):
    # retracement extreme beyond the last known hump (higher high for a sell / lower low for a buy)
    k = t["k"]
    H = A.humps[A.humps[:, 7] <= k]
    if not len(H):
        return False
    b0, v0, bh, vh, b1, v1, tr, kn = H[-1]
    return (t["extreme"] > vh) if t["side"] < 0 else (t["extreme"] < v0)
